import type { BankQuestion } from "@/lib/bank";

/** Quadratic Equations and Complex Numbers (Mathematics (JEE)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"math-quadratic-complex-1","question":"The sum of the roots of the equation 2x² − 7x + 3 = 0 is:","options":["−7/2","3/2","7/2","−3/2"],"answer":2,"explanation":"For ax² + bx + c = 0 the sum of roots is −b/a = −(−7)/2 = 7/2. The product of roots is c/a = 3/2, which is the tempting distractor.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-quadratic-complex-2","question":"The modulus of the complex number 3 + 4i is:","options":["7","5","25","√7"],"answer":1,"explanation":"|a + ib| = √(a² + b²) = √(9 + 16) = √25 = 5. 25 is |z|², not |z|.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-quadratic-complex-3","question":"The value of i²⁰²³ (where i = √−1) is:","options":["i","−i","1","−1"],"answer":1,"explanation":"Powers of i repeat with period 4. 2023 = 4 × 505 + 3, so i²⁰²³ = i³ = −i.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-quadratic-complex-4","question":"For which values of k does x² + kx + 9 = 0 have equal roots?","options":["k = ±3","k = ±18","k = ±9","k = ±6"],"answer":3,"explanation":"Equal roots need discriminant D = k² − 4 × 1 × 9 = 0, so k² = 36 and k = ±6. Taking only k = 6 misses the negative value.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-5","question":"The principal argument of z = −1 + i is:","options":["π/4","3π/4","−π/4","5π/4"],"answer":1,"explanation":"z lies in the second quadrant (real part negative, imaginary part positive), so arg z = π − tan⁻¹(1/1) = π − π/4 = 3π/4. 5π/4 is outside the principal range (−π, π].","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-6","question":"If α and β are the roots of x² − 5x + 6 = 0, then α² + β² equals:","options":["19","25","13","37"],"answer":2,"explanation":"α + β = 5 and αβ = 6, so α² + β² = (α + β)² − 2αβ = 25 − 12 = 13. (The roots are 2 and 3: 4 + 9 = 13.)","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-7","question":"If ω is a non-real cube root of unity, then ω¹⁰⁰ + ω²⁰⁰ + ω³⁰⁰ equals:","options":["0","1","−1","3"],"answer":0,"explanation":"ω³ = 1, so reduce exponents modulo 3: 100 → 1, 200 → 2, 300 → 0. The sum is ω + ω² + 1 = 0.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-8","question":"The quadratic equation with rational coefficients whose one root is 2 + √3 is:","options":["x² + 4x + 1 = 0","x² − 4x − 1 = 0","x² − 4x + 1 = 0","x² − 2x + 1 = 0"],"answer":2,"explanation":"With rational coefficients the conjugate 2 − √3 is also a root. Sum = 4, product = (2 + √3)(2 − √3) = 4 − 3 = 1, so the equation is x² − 4x + 1 = 0.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-9","question":"The value of (1 + i)/(1 − i) is:","options":["1","−1","i","−i"],"answer":2,"explanation":"Multiply numerator and denominator by (1 + i): (1 + i)²/(1 − i²) = (1 + 2i + i²)/2 = 2i/2 = i.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-10","question":"The set of all real values of a for which both roots of x² − 2ax + a² − 1 = 0 lie in the open interval (−2, 4) is:","options":["(−2, 4)","[−1, 3]","(−3, 5)","(−1, 3)"],"answer":3,"explanation":"The equation is (x − a)² = 1, so the roots are a − 1 and a + 1. We need a − 1 > −2 and a + 1 < 4, i.e. a > −1 and a < 3. Hence a ∈ (−1, 3); the end points are excluded because the interval is open.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-11","question":"If the roots of (a² + b²)x² − 2b(a + c)x + (b² + c²) = 0 are real and equal, then a, b, c are in:","options":["AP","GP","HP","AP and GP both"],"answer":1,"explanation":"D/4 = b²(a + c)² − (a² + b²)(b² + c²) = 2ab²c − a²c² − b⁴ = −(ac − b²)². D = 0 forces ac = b², so a, b, c are in GP.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-12","question":"The number of complex numbers z satisfying z² = z̄ (where z̄ is the conjugate of z) is:","options":["2","3","4","infinitely many"],"answer":2,"explanation":"Taking modulus, |z|² = |z| so z = 0 or |z| = 1. If |z| = 1, multiply z² = z̄ by z: z³ = z z̄ = 1, giving the three cube roots of unity. Total: 1 + 3 = 4 solutions.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-13","question":"The value of (1 + i√3)⁶ is:","options":["−64","64","64i","32"],"answer":1,"explanation":"1 + i√3 = 2(cos π/3 + i sin π/3). By De Moivre, (1 + i√3)⁶ = 2⁶(cos 2π + i sin 2π) = 64. Note (1 + i√3)³ = 8(cos π + i sin π) = −8, and (−8)² = 64.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-14","question":"If α and β are the roots of x² + x + 1 = 0, then α²⁰²⁴ + β²⁰²⁴ equals:","options":["−1","0","1","2"],"answer":0,"explanation":"The roots are ω and ω². Since 2024 = 3 × 674 + 2, ω²⁰²⁴ = ω² and (ω²)²⁰²⁴ = ω⁴⁰⁴⁸ = ω (4048 = 3 × 1349 + 1). Sum = ω² + ω = −1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-15","question":"For real x, the range of y = (x² − x + 1)/(x² + x + 1) is:","options":["(1/3, 3)","[0, 3]","[1/3, 3]","[−3, −1/3]"],"answer":2,"explanation":"Rearranging: (y − 1)x² + (y + 1)x + (y − 1) = 0 must have a real root, so (y + 1)² − 4(y − 1)² ≥ 0, i.e. (3 − y)(3y − 1) ≥ 0, giving 1/3 ≤ y ≤ 3. Both ends are attained (y = 3 at x = −1, y = 1/3 at x = 1), so the interval is closed.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-16","question":"If x² + px + q = 0 and x² + qx + p = 0 (p ≠ q) have a common root, then:","options":["p + q = 1","p + q = −1","pq = 1","p = −q"],"answer":1,"explanation":"Subtracting the equations gives (p − q)x + (q − p) = 0, so the common root is x = 1. Substituting in either equation: 1 + p + q = 0, i.e. p + q = −1.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-17","question":"If |z| = 2, the greatest value of |z − 3 + 4i| is:","options":["3","5","7","9"],"answer":2,"explanation":"|z − (3 − 4i)| ≤ |z| + |3 − 4i| = 2 + 5 = 7 by the triangle inequality, attained when z points opposite to 3 − 4i. The least value is 5 − 2 = 3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-18","question":"The number of real roots of x² − 5|x| + 6 = 0 is:","options":["4","2","3","0"],"answer":0,"explanation":"Put t = |x| ≥ 0: t² − 5t + 6 = 0 gives t = 2 or t = 3. Each positive t gives two values of x, so x = ±2, ±3: four real roots.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-19","question":"The set of all real values of m for which x² + 2(m − 1)x + m + 5 = 0 has at least one positive root is:","options":["(−∞, −5)","[4, ∞)","(−∞, −1]","(−∞, −1] ∪ [4, ∞)"],"answer":2,"explanation":"Real roots need D ≥ 0: (m − 1)² − (m + 5) ≥ 0 → (m − 4)(m + 1) ≥ 0 → m ≤ −1 or m ≥ 4. For m ≥ 4 the sum 2(1 − m) < 0 and product m + 5 > 0, so both roots are negative. For m ≤ −1 either the product is negative (m < −5, roots of opposite sign) or the sum is positive with product ≥ 0 (−5 ≤ m ≤ −1). Hence m ∈ (−∞, −1].","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-20","question":"Consider the following statements about ax² + bx + c = 0 with a ≠ 0:\n(I) If a, b, c are rational and 2 + √3 is a root, then 2 − √3 is the other root.\n(II) If a + b + c = 0, then the roots are 1 and a/c.\n(III) If a, b, c are real and ac < 0, the roots are real and of opposite sign.\n(IV) If a, b, c are integers and b² − 4ac is a perfect square, both roots are integers.\nHow many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(I) is true: irrational roots of a rational-coefficient quadratic occur in conjugate pairs. (II) is false: x = 1 is a root, and the other is the product c/a, not a/c. (III) is true: ac < 0 makes D = b² − 4ac > 0 and the product c/a negative. (IV) is false: 2x² − 3x + 1 = 0 has D = 1 but roots 1 and 1/2 (perfect-square D gives rational, not necessarily integer, roots). Two are correct.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-21","question":"Let ω be a non-real cube root of unity. Consider:\n(I) (1 + ω − ω²)³ = −8.\n(II) (1 − ω + ω²)(1 + ω − ω²) = 4.\n(III) ωⁿ + ω²ⁿ = −1 whenever n is a positive integer not divisible by 3.\n(IV) 1 + ωⁿ + ω²ⁿ = 3 whenever n is a positive integer divisible by 3.\nHow many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"Use 1 + ω + ω² = 0. (I): 1 + ω = −ω², so 1 + ω − ω² = −2ω² and its cube is −8ω⁶ = −8. (II): (−2ω)(−2ω²) = 4ω³ = 4. (III): if n is not a multiple of 3, ωⁿ and ω²ⁿ are ω and ω² in some order, summing to −1. (IV): if 3 | n, each power equals 1, giving 3. All four are correct.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-22","question":"The sum of all real values of x satisfying (x² − 5x + 5)^(x² + 4x − 60) = 1 is:","options":["5","3","6","13"],"answer":1,"explanation":"Three cases. Base = 1: x² − 5x + 4 = 0 → x = 1, 4. Base = −1 with an even exponent: x² − 5x + 6 = 0 → x = 2 (exponent −48, even, accepted) or x = 3 (exponent −39, odd, rejected). Exponent = 0 with nonzero base: x² + 4x − 60 = 0 → x = 6, −10 (bases 11 and 155). Sum = 1 + 4 + 2 + 6 − 10 = 3.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-23","question":"If α and β are the roots of x² − 6x + 1 = 0, then α⁴ + β⁴ equals:","options":["1154","1156","1152","1190"],"answer":0,"explanation":"Let Sₙ = αⁿ + βⁿ. Since α + β = 6 and αβ = 1, Sₙ = 6Sₙ₋₁ − Sₙ₋₂ with S₀ = 2, S₁ = 6. Then S₂ = 36 − 2 = 34, S₃ = 204 − 6 = 198, S₄ = 1188 − 34 = 1154. Alternatively S₄ = S₂² − 2(αβ)² = 34² − 2 = 1154.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-24","question":"The least positive integer n for which (√3 + i)ⁿ is a positive real number is:","options":["6","3","24","12"],"answer":3,"explanation":"√3 + i = 2(cos π/6 + i sin π/6), so (√3 + i)ⁿ = 2ⁿ(cos nπ/6 + i sin nπ/6). It is real when nπ/6 is a multiple of π (n = 6 gives −64, negative) and positive real when nπ/6 is a multiple of 2π, i.e. n = 12 (giving 4096).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-25","question":"The locus of the complex number z satisfying |z − 2i| + |z + 2i| = 10 is a conic whose eccentricity is:","options":["4/5","2/5","1/5","√21/5"],"answer":1,"explanation":"The sum of distances from the fixed points ±2i is constant (10 > 4), so the locus is an ellipse with foci (0, ±2). Then 2a = 10, a = 5, c = 2, and e = c/a = 2/5. (b² = a² − c² = 21 is a distractor source.)","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-26","question":"Consider the following statements about complex numbers:\n(I) If |z| = 1 and z ≠ −1, then (z − 1)/(z + 1) is purely imaginary or zero.\n(II) For every z, |Re z| + |Im z| ≤ √2 |z|.\n(III) arg(z̄) = −arg(z) for every non-zero z (principal values).\n(IV) |z₁ + z₂|² + |z₁ − z₂|² = 2(|z₁|² + |z₂|²) for all z₁, z₂.\nHow many of these statements are correct?","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(I) true: with z = cos θ + i sin θ, (z − 1)/(z + 1) = i tan(θ/2). (II) true: (|a| + |b|)² ≤ 2(a² + b²) by (|a| − |b|)² ≥ 0. (III) false for negative reals: if z = −3, both arg z and arg z̄ equal π (principal value), not −π. (IV) true: it is the parallelogram law. Three are correct.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-27","question":"Both roots of x² + px + q = 0 are also roots of x³ − 7x + 6 = 0. Then the value of pq is:","options":["−6","6","−1","cannot be determined without knowing which two roots"],"answer":0,"explanation":"x³ − 7x + 6 = (x − 1)(x − 2)(x + 3) has roots 1, 2, −3. If the quadratic's roots are r₁, r₂ and the third root is r₃, then p = −(r₁ + r₂) = r₃ (since r₁ + r₂ + r₃ = 0) and q = r₁r₂, so pq = r₁r₂r₃ = −6 whichever pair is chosen. Check with {1, 2}: p = −3, q = 2, pq = −6.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-28","question":"If x + 1/x = √3, then x¹² + 1/x¹² equals:","options":["−2","0","2","1"],"answer":2,"explanation":"x + 1/x = √3 = 2 cos(π/6), so x = cos(π/6) ± i sin(π/6). By De Moivre, xⁿ + 1/xⁿ = 2 cos(nπ/6), hence x¹² + 1/x¹² = 2 cos 2π = 2. (x⁶ + 1/x⁶ = 2 cos π = −2 is the trap.)","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-29","question":"If z is a non-zero complex number with |z + 2/z| = 2, then the maximum possible value of |z| is:","options":["2","√3","1 + √2","1 + √3"],"answer":3,"explanation":"Let r = |z|. By the triangle inequality, r − 2/r ≤ |z + 2/z| = 2, so r² − 2r − 2 ≤ 0 and r ≤ 1 + √3. Equality is attained for z = i(1 + √3), where z and 2/z point in opposite directions.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-30","question":"Both roots of x² + 2(k − 3)x + 9 = 0 lie in the open interval (−6, 1). The set of possible values of k is:","options":["[6, 27/4)","(6, 27/4)","(2, 9)","(−∞, 0] ∪ [6, ∞)"],"answer":0,"explanation":"Let f(x) = x² + 2(k − 3)x + 9. Need D ≥ 0: (k − 3)² ≥ 9 → k ≤ 0 or k ≥ 6; vertex 3 − k in (−6, 1) → 2 < k < 9; f(−6) > 0 → 81 − 12k > 0 → k < 27/4; f(1) > 0 → 2k + 4 > 0 → k > −2. Intersection: 6 ≤ k < 27/4. k = 6 works (double root −3), so the left end is included.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id": "math-quadratic-complex-31", "question": "The product of the roots of 3x² + 5x − 2 = 0 is:", "options": ["−2/3", "2/3", "−5/3", "5/3"], "answer": 0, "explanation": "Product of roots = c/a = −2/3. −5/3 is the sum, −b/a.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-32", "question": "The conjugate of 1/(2 − 3i) is:", "options": ["(2 + 3i)/13", "(2 − 3i)/5", "2 + 3i", "(2 − 3i)/13"], "answer": 3, "explanation": "1/(2 − 3i) = (2 + 3i)/((2 − 3i)(2 + 3i)) = (2 + 3i)/13, so its conjugate is (2 − 3i)/13.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-33", "question": "If one root of x² − 6x + k = 0 is twice the other, then k equals:", "options": ["9", "6", "8", "12"], "answer": 2, "explanation": "Let the roots be α and 2α. Then 3α = 6, so α = 2, and k = α·2α = 2 × 4 = 8.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-34", "question": "The locus of z satisfying |z − 1| = |z + 1| is:", "options": ["the imaginary axis", "the real axis", "a circle centred at the origin", "the line y = x"], "answer": 0, "explanation": "z is equidistant from 1 and −1, so it lies on the perpendicular bisector of the segment joining them, which is the line x = 0, the imaginary axis.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-35", "question": "If α and β are the roots of x² − 3x + 1 = 0, the quadratic whose roots are α/β and β/α is:", "options": ["x² − 9x + 1 = 0", "x² + 7x + 1 = 0", "x² − 7x − 1 = 0", "x² − 7x + 1 = 0"], "answer": 3, "explanation": "α + β = 3 and αβ = 1, so α² + β² = 9 − 2 = 7. Sum of new roots = (α² + β²)/αβ = 7 and product = 1, giving x² − 7x + 1 = 0.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-36", "question": "The principal argument of (1 + i√3)/(1 − i) is:", "options": ["π/12", "7π/12", "−π/12", "5π/12"], "answer": 1, "explanation": "arg(1 + i√3) = π/3 and arg(1 − i) = −π/4, so the quotient's argument is π/3 + π/4 = 7π/12, which lies in (−π, π].", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-37", "question": "The number 1 lies strictly between the roots of x² + ax + a − 3 = 0 exactly when:", "options": ["a > 1", "a < 1", "a < −1", "for every real a"], "answer": 1, "explanation": "For an upward parabola, 1 lies between the roots iff f(1) < 0: 1 + a + a − 3 = 2a − 2 < 0, so a < 1. Real distinct roots are then automatic (and the discriminant a² − 4a + 12 is always positive).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-38", "question": "The equations x² + kx + 1 = 0 and x² + x + k = 0 have exactly one common root when k equals:", "options": ["1", "2", "−1", "−2"], "answer": 3, "explanation": "Subtracting: (k − 1)x − (k − 1) = 0, so for k ≠ 1 the common root is x = 1, and 1 + k + 1 = 0 gives k = −2. For k = 1 the equations are identical and share both roots, not exactly one.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "math-quadratic-complex-39", "question": "The sum of all real roots of x² + |2x − 3| − 4 = 0 is:", "options": ["√2", "2", "2√2", "√2 − 2"], "answer": 0, "explanation": "For x ≥ 3/2: x² + 2x − 7 = 0 gives x = −1 + 2√2 ≈ 1.83 (valid). For x < 3/2: x² − 2x − 1 = 0 gives x = 1 ± √2, and only 1 − √2 is valid. Sum = (−1 + 2√2) + (1 − √2) = √2.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "math-quadratic-complex-40", "question": "For z = 3 + 4i, the area of the triangle with vertices z, iz and z + iz in the Argand plane is:", "options": ["25", "5/2", "25/2", "50"], "answer": 2, "explanation": "iz is z turned through 90°, with |iz| = |z| = 5. The points 0, z, z + iz, iz form a square of side 5, and the triangle z, iz, z + iz is half of it: 25/2.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-41", "question": "Both roots of x² − 2kx + k² + k − 5 = 0 are less than 3 exactly when:", "options": ["1 < k < 3", "k ≤ 5", "4 < k ≤ 5", "k < 1"], "answer": 3, "explanation": "Real roots need D/4 = k² − (k² + k − 5) = 5 − k ≥ 0, i.e. k ≤ 5. Both roots below 3 need f(3) > 0, i.e. k² − 5k + 4 > 0 (k < 1 or k > 4), and the vertex k < 3. All three together give k < 1.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-42", "question": "Consider, for non-zero complex numbers z₁, z₂:\n(1) |z₁ + z₂| ≤ |z₁| + |z₂|.\n(2) arg(z₁z₂) = arg z₁ + arg z₂ always holds for principal arguments.\n(3) z₁ times its conjugate equals |z₁|².\n(4) If |z₁ + z₂| = |z₁ − z₂|, then arg z₁ − arg z₂ = ±π/2.\nHow many of these statements are correct?", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) True: the triangle inequality. (2) False: the sum may need a correction of ±2π to stay in (−π, π], e.g. for z₁ = z₂ = −1 + i. (3) True. (4) True: the condition means Re(z₁ times the conjugate of z₂) = 0, so the vectors are perpendicular. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-43", "question": "The sum of the real roots of (x − 1)(x − 2)(x − 3)(x − 4) = 24 is:", "options": ["10", "0", "5", "4"], "answer": 2, "explanation": "Pair the factors: (x² − 5x + 4)(x² − 5x + 6) = 24. With t = x² − 5x: (t + 4)(t + 6) = 24, so t² + 10t = 0 and t = 0 or −10. t = 0 gives x = 0, 5; t = −10 gives x² − 5x + 10 = 0, which has no real roots. Sum = 5. 10 is the sum of all four complex roots.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-44", "question": "The number of complex numbers z satisfying z³ + z̄ = 0 (z̄ the conjugate of z) is:", "options": ["5", "4", "3", "6"], "answer": 0, "explanation": "Taking moduli: |z|³ = |z|, so |z| = 0 or 1. z = 0 works. If |z| = 1, then z̄ = 1/z, so z³ = −1/z and z⁴ = −1, which has 4 solutions. Total 5.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-45", "question": "If α and β are the roots of x² + 2x + 4 = 0, then α¹⁰ + β¹⁰ equals:", "options": ["1024", "−1024", "2048", "−512"], "answer": 1, "explanation": "The roots are −1 ± i√3 = 2ω and 2ω², where ω is a complex cube root of unity. α¹⁰ + β¹⁰ = 2¹⁰(ω¹⁰ + ω²⁰) = 1024(ω + ω²) = 1024 × (−1) = −1024.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "math-quadratic-complex-46", "question": "If z = 2 − 3i, then z·z̄ (z̄ the conjugate of z) equals:", "options": ["−5", "4 − 9i", "13", "5"], "answer": 2, "explanation": "z·z̄ = |z|² = 2² + 3² = 4 + 9 = 13, always a non-negative real number. −5 comes from wrongly using 4 − 9 (treating i² as +1).", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-47", "question": "The roots of the equation 3x² − 4x + 2 = 0 are:", "options": ["non-real complex conjugates", "real and equal", "real, distinct and rational", "real, distinct and irrational"], "answer": 0, "explanation": "D = b² − 4ac = 16 − 24 = −8 < 0, so the roots are non-real; with real coefficients they occur as a conjugate pair.", "difficulty": "easy", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-48", "question": "If α and β are the roots of 2x² + 3x − 5 = 0, then 1/α + 1/β equals:", "options": ["−3/5", "5/3", "−3/2", "3/5"], "answer": 3, "explanation": "1/α + 1/β = (α + β)/(αβ) = (−3/2)/(−5/2) = 3/5. Forgetting that the product is negative gives −3/5.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-49", "question": "The square roots of 5 + 12i are:", "options": ["±(2 + 3i)", "±(3 + 2i)", "±(3 − 2i)", "±(2 − 3i)"], "answer": 1, "explanation": "Let (a + ib)² = 5 + 12i: a² − b² = 5 and 2ab = 12; also a² + b² = |5 + 12i| = 13. So a² = 9, b² = 4 and ab > 0, giving ±(3 + 2i). Check: (3 + 2i)² = 9 − 4 + 12i = 5 + 12i; (2 + 3i)² = −5 + 12i.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-50", "question": "The expression x² − kx + 4 is positive for every real x exactly when:", "options": ["k < −4 or k > 4", "−4 < k < 4", "−4 ≤ k ≤ 4", "0 < k < 4"], "answer": 1, "explanation": "A quadratic with positive leading coefficient is positive for all x iff its discriminant is negative: k² − 16 < 0, i.e. −4 < k < 4. At k = ±4 it touches zero (a perfect square), so the end points are excluded.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-51", "question": "If ω is a non-real cube root of unity, then (1 + ω)(1 + ω²)(1 + ω⁴)(1 + ω⁸) equals:", "options": ["0", "−1", "2", "1"], "answer": 3, "explanation": "ω⁴ = ω and ω⁸ = ω², so the product is [(1 + ω)(1 + ω²)]². Now 1 + ω = −ω² and 1 + ω² = −ω, so (1 + ω)(1 + ω²) = ω³ = 1, and the product is 1² = 1.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-52", "question": "The sum of the real roots of 4ˣ − 3·2^(x + 1) + 8 = 0 is:", "options": ["3", "6", "2", "8"], "answer": 0, "explanation": "Put t = 2ˣ: t² − 6t + 8 = 0, so t = 2 or 4, i.e. x = 1 or 2. The sum of the x-values is 3; 6 is the sum of the t-values, a common slip.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-53", "question": "The locus of z satisfying |z − 3| = 2|z| in the Argand plane is a circle with:", "options": ["centre (1, 0) and radius 2", "centre (−1, 0) and radius 4", "centre (−1, 0) and radius 2", "centre (3, 0) and radius 2"], "answer": 2, "explanation": "With z = x + iy: (x − 3)² + y² = 4(x² + y²) ⇒ 3x² + 3y² + 6x − 9 = 0 ⇒ x² + y² + 2x − 3 = 0 ⇒ (x + 1)² + y² = 4. Centre (−1, 0), radius 2 (an Apollonius circle).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-54", "question": "The points 0, z₁ = 1 + i and z₂ form an equilateral triangle in the Argand plane. One possible value of z₂ is:", "options": ["(1 + √3)/2 + i(1 + √3)/2", "−1 + i", "(1 − √3) + i(1 + √3)", "(1 − √3)/2 + i(1 + √3)/2"], "answer": 3, "explanation": "z₂ is z₁ rotated about 0 by ±60°: z₂ = (1 + i)(1/2 + i√3/2) = (1 − √3)/2 + i(1 + √3)/2 (the other choice uses −60°). Check |z₂| = √2 = |z₁|. −1 + i is a 90° rotation, which gives an isosceles right triangle.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-55", "question": "The locus of z satisfying arg((z − 1)/(z + 1)) = π/2 is:", "options": ["the whole circle |z| = 1", "the upper half of the circle |z| = 1, without the points ±1", "the lower half of the circle |z| = 1", "the imaginary axis"], "answer": 1, "explanation": "The segment from −1 to 1 subtends a right angle at z, so z is on the circle with diameter from −1 to 1, i.e. |z| = 1. The argument is +π/2 (not −π/2) only on the upper half: for z = i, (i − 1)/(i + 1) = i, arg = π/2. Points ±1 are excluded since the argument is undefined there.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-56", "question": "The value of Σ i^(k!) for k = 0 to 100 (i = √−1) is:", "options": ["97 + 2i", "95 − 2i", "95 + 2i", "99"], "answer": 2, "explanation": "k = 0, 1: i^1 = i (twice). k = 2: i² = −1. k = 3: i⁶ = −1. For k ≥ 4, k! is a multiple of 4, so i^(k!) = 1 for 97 values. Sum = 2i − 2 + 97 = 95 + 2i.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-57", "question": "If z = (√3 + i)/2, then (z²⁰¹ − i)⁸ equals:", "options": ["256", "−256", "1", "16"], "answer": 0, "explanation": "z = cos(π/6) + i sin(π/6), so z²⁰¹ = cis(201π/6) = cis(201π/6 − 32π) = cis(9π/6) = cis(3π/2) = −i. Then z²⁰¹ − i = −2i and (−2i)⁸ = 2⁸·i⁸ = 256.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-58", "question": "The number of integers x satisfying (x² − 5x + 4)/(x² − 4) ≤ 0 is:", "options": ["5", "4", "6", "3"], "answer": 0, "explanation": "(x − 1)(x − 4)/((x − 2)(x + 2)) ≤ 0. The sign chart with critical points −2, 1, 2, 4 gives the solution (−2, 1] ∪ (2, 4] (x = ±2 excluded). Integers: −1, 0, 1, 3, 4, i.e. 5.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-59", "question": "The set of complex numbers z satisfying (1 + i)z = (1 − i)z̄ (z̄ the conjugate of z) is:", "options": ["the line x − y = 0", "the real axis", "the line x + y = 0", "the circle |z| = 1"], "answer": 2, "explanation": "With z = x + iy: (1 + i)(x + iy) = (x − y) + i(x + y) and (1 − i)(x − iy) = (x − y) − i(x + y). Equality forces x + y = 0, so the locus is the line y = −x.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-60", "question": "The value of Σ (k = 1 to 6) [sin(2πk/7) − i cos(2πk/7)] is:", "options": ["−i", "i", "1", "0"], "answer": 1, "explanation": "sin θ − i cos θ = −i(cos θ + i sin θ), so the sum is −i Σ (k = 1 to 6) e^(2πik/7). The seven 7th roots of unity add to 0, so the six non-real ones add to −1. Sum = −i·(−1) = i.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-quadratic-complex-61", "question": "Let α = cos(2π/5) + i sin(2π/5). Then (1 − α)(1 − α²)(1 − α³)(1 − α⁴) equals:", "options": ["1", "0", "4", "5"], "answer": 3, "explanation": "α, α², α³, α⁴ are the roots of (z⁵ − 1)/(z − 1) = z⁴ + z³ + z² + z + 1, so this polynomial equals (z − α)(z − α²)(z − α³)(z − α⁴). Putting z = 1 gives the product = 1 + 1 + 1 + 1 + 1 = 5.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-quadratic-complex-62", "question": "If a, b, c are real and the equations ax² + bx + c = 0 and x² + 2x + 3 = 0 have a common root, then a : b : c equals:", "options": ["3 : 2 : 1", "1 : 3 : 2", "1 : 2 : 3", "it cannot be determined"], "answer": 2, "explanation": "x² + 2x + 3 = 0 has D = 4 − 12 < 0, so its roots are a non-real conjugate pair. If one is a root of the real quadratic ax² + bx + c = 0, its conjugate is too, so both equations have the same roots and a/1 = b/2 = c/3.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-63", "question": "Let α and β be the roots of x² − 4x − 3 = 0 and aₙ = αⁿ + βⁿ. Then (a₁₂ − 3a₁₀)/a₁₁ equals:", "options": ["3", "−4", "1", "4"], "answer": 3, "explanation": "α² = 4α + 3, so αⁿ⁺² = 4αⁿ⁺¹ + 3αⁿ, and likewise for β. Adding: a₁₂ = 4a₁₁ + 3a₁₀, so a₁₂ − 3a₁₀ = 4a₁₁ and the ratio is 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-64", "question": "Both roots of (k − 2)x² + 8x + k + 4 = 0 are real and negative exactly when:", "options": ["2 < k ≤ 4", "−6 ≤ k ≤ 4", "k > 2", "−4 < k ≤ 4"], "answer": 0, "explanation": "Need: D ≥ 0 ⇒ 64 − 4(k − 2)(k + 4) ≥ 0 ⇒ k² + 2k − 24 ≤ 0 ⇒ −6 ≤ k ≤ 4; sum −8/(k − 2) < 0 ⇒ k > 2; product (k + 4)/(k − 2) > 0 ⇒ k > 2 or k < −4. Together 2 < k ≤ 4. [−6, 4] is the discriminant condition alone.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-65", "question": "If a, b, c are real numbers with a ≠ 0 and a + b + c = 0, then the equation 3ax² + 2bx + c = 0 has:", "options": ["no real root", "at least one root in [0, 1]", "both roots negative", "both roots greater than 1"], "answer": 1, "explanation": "Let f(x) = ax³ + bx² + cx. Then f(0) = 0 and f(1) = a + b + c = 0, so by Rolle's theorem f′(x) = 3ax² + 2bx + c vanishes at some point of (0, 1). The other options fail, e.g. a = 1, b = −1, c = 0 gives roots 0 and 2/3.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-quadratic-complex-66", "question": "For non-zero complex numbers z₁, z₂, how many of the following are correct?\n(1) |z₁z₂| = |z₁||z₂|.\n(2) |z₁ + z₂|² + |z₁ − z₂|² = 2(|z₁|² + |z₂|²).\n(3) If |z₁ + z₂| = |z₁| + |z₂|, then arg z₁ = arg z₂.\n(4) Re(z) = |z| holds only for z = 0.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "(1) is true. (2) is the parallelogram law, true. (3) is true: equality in the triangle inequality means z₁ and z₂ point the same way. (4) is false: Re(z) = |z| for every non-negative real z, e.g. z = 5. So three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-67", "question": "Assertion (A): If a, b, c are odd integers, the equation ax² + bx + c = 0 cannot have a rational root.\nReason (R): For odd integers a, b, c, the discriminant b² − 4ac is never a perfect square.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "For odd b, b² ≡ 1 (mod 8), and 4ac ≡ 4 (mod 8) since ac is odd. So b² − 4ac ≡ 5 (mod 8), but squares are 0, 1 or 4 (mod 8): D is not a perfect square. Rational roots of an integer quadratic need D to be a perfect square, so R explains A.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-quadratic-complex-68", "question": "The number of complex numbers z satisfying both |z − 1| + |z − 5| = 4 and |z − 3| = 1 is:", "options": ["4", "2", "0", "infinitely many"], "answer": 1, "explanation": "The distance between 1 and 5 is exactly 4, so |z − 1| + |z − 5| = 4 is not an ellipse but the segment from 1 to 5 on the real axis. The circle |z − 3| = 1 meets this segment only at z = 2 and z = 4. Treating it as an ellipse gives the trap answer 4.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-69", "question": "The number of real solutions of |x² − 4x + 3| = x − 1 is:", "options": ["2", "4", "3", "1"], "answer": 2, "explanation": "Need x ≥ 1. Case x² − 4x + 3 ≥ 0 (x ≤ 1 or x ≥ 3): x² − 5x + 4 = 0 ⇒ x = 1, 4, both valid. Case 1 ≤ x ≤ 3: −(x² − 4x + 3) = x − 1 ⇒ x² − 3x + 2 = 0 ⇒ x = 1, 2, both valid. Distinct solutions: 1, 2, 4, so 3 (counting x = 1 twice gives the trap 4).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-70", "question": "The roots of x² − x + p = 0 are α, β and the roots of x² − 4x + q = 0 are γ, δ. If α, β, γ, δ (in this order) form a geometric progression and p, q are integers, then (p, q) equals:", "options": ["(2, 32)", "(−2, −32)", "(−2, 32)", "(2/9, 32/9)"], "answer": 1, "explanation": "Let the terms be a, ar, ar², ar³. Then a(1 + r) = 1 and ar²(1 + r) = 4, so r² = 4. r = 2 gives a = 1/3 and p = 2/9 (not an integer); r = −2 gives a = −1, terms −1, 2, −4, 8, so p = (−1)(2) = −2 and q = (−4)(8) = −32.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-quadratic-complex-71","question":"The number of complex numbers z with |z| = 1 that satisfy |z³ + z̄³| = 1 (z̄ the conjugate of z) is:","options":["12","8","6","16"],"answer":0,"explanation":"On |z| = 1 write z = e^(iθ); then z̄³ = 1/z³ and z³ + z̄³ = 2cos 3θ, so the condition is |cos 3θ| = 1/2. As θ runs over [0, 2π), 3θ runs over [0, 6π), and each of cos 3θ = 1/2 and cos 3θ = −1/2 has 2 solutions per period of 3θ, giving 2 × 3 + 2 × 3 = 12 (6 is what you get by counting only cos 3θ = 1/2).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-quadratic-complex-72", "question": "The area of the region of the Argand plane where both |z − 2| ≤ 2 and |z − 2i| ≤ 2 hold is:", "options": ["π − 2", "2π − 4", "4π − 8", "π − 1"], "answer": 1, "explanation": "Both circles have radius 2 and their centres (2, 0) and (0, 2) are 2√2 apart; they meet at 0 and 2 + 2i, and each circle's common chord subtends a right angle at its centre. Each half of the lens is a quarter-circle minus a right triangle: π·4/4 − (1/2)·2·2 = π − 2, so the area is 2(π − 2) = 2π − 4 (π − 2 is only one half).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-73", "question": "The sum of all real values of a for which both roots of x² − ax + 2a = 0 are integers is:", "options": ["8", "15", "16", "17"], "answer": 2, "explanation": "If the roots are r, s then r + s = a and rs = 2a = 2(r + s), so (r − 2)(s − 2) = 4. The factor pairs (1, 4), (2, 2), (−1, −4), (−2, −2) and their reverses give (r, s) = (3, 6), (4, 4), (1, −2), (0, 0), i.e. a = 9, 8, −1, 0, whose sum is 16 (forgetting the negative factor pairs gives 17).", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-quadratic-complex-74","question":"For f(x) = x² − 2ax + 4, the roots α < β satisfy α < 1 < 2 < β exactly when:","options":["a > 2","2 < a < 5/2","a ≥ 2","a > 5/2"],"answer":3,"explanation":"Since the parabola opens upward, both 1 and 2 lie strictly between the roots iff f(1) < 0 and f(2) < 0. f(1) = 5 − 2a < 0 gives a > 5/2 and f(2) = 8 − 4a < 0 gives a > 2; both must hold, so a > 5/2 (using only f(2) < 0 gives the trap a > 2).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-75","question":"As z moves along the imaginary axis, the least value of |z − 3| + |z − 1 − 4i| is:","options":["4√2","5","2√5","√34"],"answer":0,"explanation":"The points A(3, 0) and B(1, 4) are on the same side of the line x = 0, so reflect A to A′(−3, 0); the least sum is A′B = √(4² + 4²) = 4√2, attained where A′B crosses the imaginary axis. 2√5 = AB is smaller than any achievable value because the path must touch the axis.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-76","question":"For complex z with |z − 2 − 2i| = 1, the least value of the principal argument of z is:","options":["tan⁻¹((4 + √7)/3)","tan⁻¹((4 − √7)/3)","π/4 − π/6","tan⁻¹(1/√7)"],"answer":1,"explanation":"The centre 2 + 2i is at distance 2√2 from O in direction π/4, and a tangent from O makes angle φ with that direction where sin φ = 1/(2√2), so tan φ = 1/√7. The least argument is π/4 − φ, and tan(π/4 − φ) = (1 − 1/√7)/(1 + 1/√7) = (√7 − 1)/(√7 + 1) = (4 − √7)/3; tan⁻¹((4 + √7)/3) is the greatest argument.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-quadratic-complex-77","question":"Let ω be a non-real cube root of unity. The number of ordered pairs (a, b) with a, b ∈ {1, 2, …, 10} such that ωᵃ + ωᵇ + 1 = 0 is:","options":["12","36","24","48"],"answer":2,"explanation":"1 + ωᵃ + ωᵇ = 0 forces {ωᵃ, ωᵇ} = {ω, ω²}, i.e. one exponent ≡ 1 and the other ≡ 2 (mod 3); a ≡ b ≡ 0 gives 3 and a ≡ b otherwise gives 1 + 2ωᵃ ≠ 0. In 1 to 10 there are 4 numbers ≡ 1 (1, 4, 7, 10) and 3 numbers ≡ 2 (2, 5, 8), so the ordered pairs number 2 × 4 × 3 = 24 (12 if order is ignored).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-78","question":"With [x] the greatest integer ≤ x, the number of real solutions of x² − 4[x] + 3 = 0 is:","options":["1","2","4","3"],"answer":3,"explanation":"Put [x] = n, so x² = 4n − 3 needs n ≥ 1, which forces x ≥ 1 and x = √(4n − 3) ∈ [n, n + 1). The condition n² ≤ 4n − 3 gives 1 ≤ n ≤ 3, and 4n − 3 < (n + 1)² always holds, so x = 1, √5, 3 — three solutions (negative x is impossible because it would need n ≤ −1).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "math-quadratic-complex-79", "question": "Assertion (A): If |z₁| = |z₂| = 1 and 1 + z₁z₂ ≠ 0, then (z₁ + z₂)/(1 + z₁z₂) is a real number.\nReason (R): A complex number w is real if and only if w̄ = w.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Using z̄₁ = 1/z₁ and z̄₂ = 1/z₂, the conjugate of w = (z₁ + z₂)/(1 + z₁z₂) is (1/z₁ + 1/z₂)/(1 + 1/(z₁z₂)) = (z₁ + z₂)/(z₁z₂ + 1) = w. So w̄ = w and w is real exactly by the criterion in R, which is why A holds.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "math-quadratic-complex-80", "question": "How many of the following statements are correct?\n(1) If |z₁| = |z₂| = |z₃| = 1 and z₁ + z₂ + z₃ = 0, then z₁² + z₂² + z₃² = 0.\n(2) If |z + 1/z| = 1, the greatest possible value of |z| is (1 + √5)/2.\n(3) The sum of the squares of the four non-real fifth roots of unity is −1.\n(4) arg z + arg z̄ = 0 for every non-zero complex z (principal arguments).", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(1) z₁² + z₂² + z₃² = (Σz)² − 2z₁z₂z₃(z̄₁ + z̄₂ + z̄₃) = 0, true. (2) |z| − 1/|z| ≤ |z + 1/z| = 1 gives |z| ≤ (1 + √5)/2, attained at z = i(1 + √5)/2, true. (3) The squares of all five roots sum to 0, so the four non-real ones give 0 − 1 = −1, true. (4) fails for negative real z, where both arguments are π; so exactly three are correct.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"math-quadratic-complex-81","question":"If ω₁, ω₂, …, ω₈ are the eight 9th roots of unity other than 1, then Σ (k = 1 to 8) 1/(1 − ωₖ) equals:","options":["4","0","9/2","8"],"answer":0,"explanation":"The roots pair up as ωₖ and ω̄ₖ, and for |ω| = 1, 1/(1 − ω) + 1/(1 − ω̄) = (2 − ω − ω̄)/(2 − ω − ω̄) = 1. So each term has real part 1/2 and the imaginary parts cancel, giving 8 × 1/2 = 4 (in general (n − 1)/2 for nth roots).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-quadratic-complex-82","question":"For the values of k for which x² − 2kx + k² + k − 6 = 0 has real roots α and β, the least value of α² + β² is:","options":["11","23/2","12","6"],"answer":1,"explanation":"Real roots need D/4 = k² − (k² + k − 6) = 6 − k ≥ 0, i.e. k ≤ 6. Then α² + β² = (2k)² − 2(k² + k − 6) = 2k² − 2k + 12, least at k = 1/2 (allowed, as 1/2 ≤ 6) with value 1/2 − 1 + 12 = 23/2; taking k = 0 gives the trap 12.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-83","question":"The locus of z satisfying Re((z − 2)/(z − 2i)) = 0 (with z ≠ 2i) is a circle with:","options":["centre 0 and radius 2","centre 1 + i and radius 2","centre 1 + i and radius √2","centre 2 + 2i and radius 2"],"answer":2,"explanation":"Re((z − 2)/(z − 2i)) = 0 means the vectors from 2i to z and from 2 to z are perpendicular (or z = 2), so z sees the segment from 2 to 2i at a right angle. The locus is the circle on that segment as diameter: centre (2 + 2i)/2 = 1 + i, radius |2 − 2i|/2 = √2, with the point 2i removed.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "math-quadratic-complex-84", "question": "The points A = 1 + 2i and C = 5 + 4i are opposite vertices of a square in the Argand plane. The other two vertices are:", "options": ["3 + i and 3 + 5i", "4 + i and 2 + 5i", "6 + i and 5i", "5 + 2i and 1 + 4i"], "answer": 1, "explanation": "The centre is M = (A + C)/2 = 3 + 3i and A − M = −2 − i. Rotating this half-diagonal by ±90° (multiplying by ±i) gives ±(1 − 2i), so the vertices are M + (1 − 2i) = 4 + i and M − (1 − 2i) = 2 + 5i; 5 + 2i and 1 + 4i make a rectangle with sides parallel to the axes, not a square.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-quadratic-complex-85","question":"The remainder when x²⁰²⁷ + x¹⁰⁰¹ + 3 is divided by x² + x + 1 is:","options":["2x + 1","3","−2x − 1","1 − 2x"],"answer":3,"explanation":"The roots of x² + x + 1 are ω and ω². Since 2027 ≡ 2 and 1001 ≡ 2 (mod 3), the polynomial equals 2ω² + 3 = 2(−1 − ω) + 3 = 1 − 2ω at x = ω (and the conjugate at ω²). A remainder ax + b with aω + b = 1 − 2ω gives a = −2, b = 1, i.e. 1 − 2x.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-quadratic-complex-86","question":"In x² + bx + c = 0, one student copied b wrongly and got roots 2 and 6; another copied c wrongly and got roots 3 and −7. The correct roots are:","options":["−2 ± 2√2 i","−2 ± 2√2","−4 and −3","2 ± 2√2 i"],"answer":0,"explanation":"The first student had the right c, so c = 2 × 6 = 12; the second had the right b, so −b = 3 + (−7) = −4 and b = 4. The correct equation x² + 4x + 12 = 0 has roots (−4 ± √(16 − 48))/2 = −2 ± 2√2 i (mixing up which coefficient each student kept gives real roots).","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-87","question":"A quadratic x² + bx + c = 0 is formed by taking b and c as the scores on two throws of a die (b, c ∈ {1, 2, …, 6}). The number of ordered pairs (b, c) for which the equation has real roots is:","options":["16","19","21","17"],"answer":1,"explanation":"Real roots need b² ≥ 4c. Counting c for each b: b = 1 → 0, b = 2 → 1, b = 3 → 2, b = 4 → 4, b = 5 → 6, b = 6 → 6, total 19. Using b² > 4c (distinct roots) drops (2, 1) and (4, 4) and gives the trap 17.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-88","question":"The product of all real values of x satisfying x^(log₁₀ x) = 100x is:","options":["100","1/10","10","1000"],"answer":2,"explanation":"Take log₁₀ (x > 0): (log x)² = 2 + log x, so t² − t − 2 = 0 with t = log x, giving t = 2 or t = −1. Then x = 100 or 1/10, and the product is 10 (equivalently 10 raised to the sum of the t-values, 10¹).","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "math-quadratic-complex-89", "question": "The set of all real a for which x² − 2ax + a + 2 ≥ 0 for every x ∈ [0, 3] is:", "options": ["[−1, 2]", "[−2, 2]", "[−2, 11/5]", "(−∞, 2]"], "answer": 1, "explanation": "The minimum over [0, 3] depends on where the vertex x = a lies. If a ≤ 0, need f(0) = a + 2 ≥ 0, so −2 ≤ a ≤ 0; if 0 < a < 3, need f(a) = −a² + a + 2 ≥ 0, so 0 < a ≤ 2; if a ≥ 3, need f(3) = 11 − 5a ≥ 0, impossible. Hence [−2, 2]; demanding D ≤ 0 (positivity for all real x) wrongly gives [−1, 2].", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "math-quadratic-complex-90", "question": "The minimum value of |z|² + |z − 3|² + |z − 6i|² over all complex z is:", "options": ["15", "25", "45", "30"], "answer": 3, "explanation": "A sum Σ|z − aₖ|² is least at the centroid G = (0 + 3 + 6i)/3 = 1 + 2i. There the sum is |1 + 2i|² + |−2 + 2i|² + |1 − 4i|² = 5 + 8 + 17 = 30.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"math-quadratic-complex-91","question":"If α is a non-real 7th root of unity, the number α + α² + α⁴ is a root of:","options":["x² + x + 2 = 0","x² + x − 2 = 0","x² + 2x + 2 = 0","x² − x + 2 = 0"],"answer":0,"explanation":"Let s = α + α² + α⁴ and t = α³ + α⁵ + α⁶. Then s + t = −1 (sum of the non-real 7th roots) and st expands to 3 + (α + α² + … + α⁶) = 3 − 1 = 2. So s, t are the roots of x² + x + 2 = 0, namely (−1 ± i√7)/2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-quadratic-complex-92","question":"If 1, α₁, α₂, …, α₆ are the seventh roots of unity, then (2 − α₁)(2 − α₂)…(2 − α₆) equals:","options":["1","127","128","63"],"answer":1,"explanation":"x⁷ − 1 = (x − 1)(x − α₁)…(x − α₆), so (x − α₁)…(x − α₆) = 1 + x + x² + … + x⁶. Putting x = 2 gives 2⁷ − 1 = 127 (128 forgets the subtracted 1).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-93","question":"If |z| = 1 and z ≠ ±1, then z/(1 − z²) always lies on:","options":["the real axis","the circle |w| = 1/2","the imaginary axis","the line Re w = 1/2"],"answer":2,"explanation":"Divide numerator and denominator by z: z/(1 − z²) = 1/(1/z − z) = 1/(z̄ − z), since 1/z = z̄ on the unit circle. With z = cos θ + i sin θ, z̄ − z = −2i sin θ, so the value is i/(2 sin θ), purely imaginary.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-94","question":"The least positive integer a for which some quadratic ax² + bx + c with integer b and c has two distinct roots in the open interval (0, 1) is:","options":["3","4","6","5"],"answer":3,"explanation":"If the roots are r ≠ s in (0, 1), f(0)·f(1) = a²·rs(1 − r)(1 − s) < a²/16, since x(1 − x) ≤ 1/4 with equality only at 1/2. But f(0) = c and f(1) = a + b + c are positive integers, so f(0)f(1) ≥ 1 and a² > 16, i.e. a ≥ 5; a = 5 works with 5x² − 5x + 1 (roots (5 ± √5)/10).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"math-quadratic-complex-95","question":"For |z| = 1, the greatest value of |z + 1| + |z − 1| is:","options":["2√2","2","3","4"],"answer":0,"explanation":"With z = e^(iθ), |z + 1| = 2|cos(θ/2)| and |z − 1| = 2|sin(θ/2)|, so the sum is 2(|cos(θ/2)| + |sin(θ/2)|) ≤ 2√2, attained at z = ±i. 4 comes from the triangle-inequality bound 2 + 2, which cannot be reached since |z + 1| and |z − 1| cannot both be 2.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"math-quadratic-complex-96","question":"The modulus of the complex number (3 + 4i)(5 − 12i) is:","options":["65","63","56","33"],"answer":0,"explanation":"Modulus is multiplicative: |z₁z₂| = |z₁||z₂| = 5 × 13 = 65. There is no need to expand the product (which is 63 − 16i, giving √(3969 + 256) = 65 as a check).","difficulty":"easy","source":"JEE Main"},
  {"id":"math-quadratic-complex-97","question":"If α and β are the roots of x² − 4x + 1 = 0, then α/β + β/α equals:","options":["16","12","14","18"],"answer":2,"explanation":"α + β = 4 and αβ = 1, so α² + β² = 16 − 2 = 14. Hence α/β + β/α = (α² + β²)/(αβ) = 14.","difficulty":"easy","source":"JEE Main"},
  {"id":"math-quadratic-complex-98","question":"The value of (1 + i)¹⁰ / (1 − i)⁸ is:","options":["−2i","2","−2","2i"],"answer":3,"explanation":"(1 + i)² = 2i and (1 − i)² = −2i. So (1 + i)¹⁰ = (2i)⁵ = 32i and (1 − i)⁸ = (−2i)⁴ = 16. The quotient is 32i/16 = 2i.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-99","question":"If α and β are the roots of x² − (k − 2)x − (k + 1) = 0, the least value of α² + β² as k varies over the reals is:","options":["6","4","5","9/2"],"answer":2,"explanation":"The discriminant (k − 2)² + 4(k + 1) = k² + 8 is always positive, so the roots are real for every k. α² + β² = (k − 2)² + 2(k + 1) = k² − 2k + 6 = (k − 1)² + 5, least value 5 at k = 1.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-100","question":"If z = (2 + i)/(1 − 2i), then z²⁰²⁶ + z²⁰²⁷ equals:","options":["1 + i","−1 − i","−1 + i","1 − i"],"answer":1,"explanation":"Multiply by the conjugate: z = (2 + i)(1 + 2i)/5 = (2 + 5i − 2)/5 = i. Powers of i repeat with period 4, so i²⁰²⁶ = i² = −1 and i²⁰²⁷ = i³ = −i. The sum is −1 − i.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-101","question":"The number of integer values of k for which the roots of x² − 2kx + 16 = 0 are non-real is:","options":["7","9","8","6"],"answer":0,"explanation":"Non-real roots need a negative discriminant: 4k² − 64 < 0, i.e. −4 < k < 4. The integers are −3, −2, …, 3, which is 7 values (k = ±4 give equal real roots).","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-102","question":"The point 2 + i is rotated about the point 1 − i through π/2 in the anticlockwise sense. Its new position is:","options":["−1","3 − 2i","−1 + 2i","1 − 2i"],"answer":0,"explanation":"Rotation about Q by π/2 anticlockwise is z′ − Q = i(z − Q). Here z − Q = 1 + 2i, so z′ = (1 − i) + i(1 + 2i) = 1 − i + i − 2 = −1. The option 3 − 2i comes from rotating clockwise.","difficulty":"moderate","source":"JEE Main"},
  {"id":"math-quadratic-complex-103","question":"For every complex number z with |z| = 1 and z ≠ 1, the real part of 1/(1 − z) is:","options":["0","1/2","1","dependent on z"],"answer":1,"explanation":"Write z = e^(iθ). Then 1 − z = −2i sin(θ/2) e^(iθ/2), so 1/(1 − z) = (i/2) e^(−iθ/2)/sin(θ/2) = 1/2 + (i/2) cot(θ/2). The real part is always 1/2: the image of the unit circle under this map is the line Re w = 1/2.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-104","question":"ABCD is a square in the Argand plane with its vertices in anticlockwise order. If A = 2 + i and B = 4 + 3i, then D is:","options":["4 − i","2 + 5i","3i","6 + i"],"answer":2,"explanation":"Going anticlockwise, AD is AB rotated by +90°: D − A = i(B − A) = i(2 + 2i) = −2 + 2i. So D = (2 + i) + (−2 + 2i) = 3i. (C = B + i(B − A) = 2 + 5i, and 4 − i is D for a clockwise labelling.)","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-105","question":"If tan 15° and tan 30° are the roots of x² + px + q = 0, then q − p equals:","options":["0","−1","2","1"],"answer":3,"explanation":"Since 15° + 30° = 45°, tan(15° + 30°) = (t₁ + t₂)/(1 − t₁t₂) = 1, so t₁ + t₂ = 1 − t₁t₂. With t₁ + t₂ = −p and t₁t₂ = q this reads −p = 1 − q, i.e. q − p = 1. No surd values of tan 15° are needed.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-106","question":"If ω is a non-real cube root of unity, then Σ (k = 1 to 20) (k + ω)(k + ω²) equals:","options":["2870","2660","2680","3080"],"answer":2,"explanation":"(k + ω)(k + ω²) = k² + k(ω + ω²) + ω³ = k² − k + 1. So the sum is Σk² − Σk + 20 = 2870 − 210 + 20 = 2680.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-107","question":"If |z₁| = 3, |z₂| = 4 and |z₁ + z₂| = 5, then |z₁ − z₂| equals:","options":["5","1","7","√7"],"answer":0,"explanation":"Parallelogram law: |z₁ + z₂|² + |z₁ − z₂|² = 2(|z₁|² + |z₂|²) = 50. So |z₁ − z₂|² = 50 − 25 = 25 and |z₁ − z₂| = 5. Geometrically z₁ ⊥ z₂, so both diagonals of the rectangle are equal.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-108","question":"The number of integer values of a for which both roots of x² − 2ax + a + 6 = 0 are real and greater than 1 is:","options":["3","5","infinitely many","4"],"answer":3,"explanation":"Conditions for f(x) = x² − 2ax + a + 6: D ≥ 0 gives a² − a − 6 ≥ 0, i.e. a ≤ −2 or a ≥ 3; the vertex a > 1; and f(1) = 7 − a > 0, i.e. a < 7. Together 3 ≤ a < 7, so a = 3, 4, 5, 6: four values (a = 3 gives the double root 3).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-109","question":"If 1, α₁, α₂, …, α₉ are the tenth roots of unity, then Σ (k = 1 to 9) |1 − αₖ|² equals:","options":["10","20","18","9"],"answer":1,"explanation":"|1 − α|² = (1 − α)(1 − ᾱ) = 2 − (α + ᾱ). Summing over all ten roots (the k = 0 term is 0) gives 2 × 10 − 2 Re(Σα) = 20 − 0 = 20, since the tenth roots of unity add up to 0.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-110","question":"If α and β are the roots of x² + 3x − 1 = 0, the quadratic equation whose roots are 1/(α + 3) and 1/(β + 3) is:","options":["x² − 3x − 1 = 0","x² + 3x − 1 = 0","x² + 3x + 1 = 0","x² − 3x + 1 = 0"],"answer":1,"explanation":"From α² + 3α = 1 we get α(α + 3) = 1, so 1/(α + 3) = α; likewise 1/(β + 3) = β. The new roots are just α and β again, so the required equation is x² + 3x − 1 = 0 itself.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-111","question":"If |z − 1 − i| ≤ 3, the greatest value of |iz + 5 − 4i| is:","options":["2","5","3 + √41","8"],"answer":3,"explanation":"|iz + 5 − 4i| = |i| |z + (5 − 4i)/i| = |z − (4 + 5i)|, the distance of z from 4 + 5i. The centre 1 + i is at distance √(9 + 16) = 5 from 4 + 5i, so over the disc of radius 3 the greatest distance is 5 + 3 = 8 (and the least is 2).","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-112","question":"The number of real solutions of |x − 1| + |x − 2| + |x − 3| = 2 is:","options":["1","0","2","infinitely many"],"answer":0,"explanation":"The sum of distances from 1, 2, 3 is a convex function minimised at the median x = 2, where its value is 1 + 0 + 1 = 2. Since the minimum value is exactly 2 and it is attained only at x = 2 (the slope is −1 just left and +1 just right), there is exactly one solution.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-113","question":"If α, β, γ are the roots of x³ − 3x + 1 = 0, then 1/(1 + α) + 1/(1 + β) + 1/(1 + γ) equals:","options":["3","−1","0","1"],"answer":2,"explanation":"Put y = x + 1: the roots y = 1 + α etc. satisfy (y − 1)³ − 3(y − 1) + 1 = y³ − 3y² + 3 = 0. For this cubic Σ1/y = (Σ yᵢyⱼ)/(y₁y₂y₃) = 0/(−3) = 0, because the coefficient of y is 0.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-114","question":"The area of the region of the Argand plane in which |z| ≤ 2 and Re z ≥ 1 is:","options":["2π/3 − √3","4π/3 + √3","π − √3/2","4π/3 − √3"],"answer":3,"explanation":"The chord x = 1 cuts the circle of radius 2 at angles ±60°, so it subtends 2π/3 at the centre. The segment area is (1/2)r²(θ − sin θ) = 2(2π/3 − √3/2) = 4π/3 − √3.","difficulty":"hard","source":"JEE Main"},
  {"id":"math-quadratic-complex-115","question":"The least value of |z − 1| + |z + 1| + |z − i√3| as z ranges over the complex numbers is:","options":["3","2 + √3","2√3","4"],"answer":2,"explanation":"The points 1, −1 and i√3 form an equilateral triangle of side 2. The sum of distances to the vertices is least at the Fermat point, which for an equilateral triangle is the centre i/√3, at distance 2/√3 from each vertex. The minimum is 3 × 2/√3 = 2√3 ≈ 3.46.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-116","question":"If |z₁| = |z₂| = |z₃| = 2 and |z₁ + z₂ + z₃| = 1, then |z₁z₂ + z₂z₃ + z₃z₁| equals:","options":["1","2","4","8"],"answer":1,"explanation":"On |z| = 2, z̄ = 4/z. So z₁z₂ + z₂z₃ + z₃z₁ = z₁z₂z₃(1/z₁ + 1/z₂ + 1/z₃) = z₁z₂z₃ (z̄₁ + z̄₂ + z̄₃)/4. Taking moduli: 8 × 1/4 = 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-117","question":"If ζ₁, ζ₂, ζ₃, ζ₄ are the fifth roots of unity other than 1, then (ζ₁² + ζ₁ + 1)(ζ₂² + ζ₂ + 1)(ζ₃² + ζ₃ + 1)(ζ₄² + ζ₄ + 1) equals:","options":["1","0","5","−1"],"answer":0,"explanation":"ζ² + ζ + 1 = (ζ − ω)(ζ − ω²), and Π(x − ζₖ) = x⁴ + x³ + x² + x + 1 = (x⁵ − 1)/(x − 1). So the product equals [(ω⁵ − 1)/(ω − 1)] × [(ω¹⁰ − 1)/(ω² − 1)] = [(ω² − 1)/(ω − 1)] × [(ω − 1)/(ω² − 1)] = 1.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-118","question":"The set of all real x satisfying √(x − 2 − 2√(x − 3)) + √(x + 1 − 4√(x − 3)) = 1 is:","options":["[4, 7]","{4, 7}","[3, 7]","the empty set"],"answer":0,"explanation":"Put t = √(x − 3) ≥ 0, so x = t² + 3. Then x − 2 − 2t = (t − 1)² and x + 1 − 4t = (t − 2)², and the equation becomes |t − 1| + |t − 2| = 1. This holds for every t in [1, 2], i.e. 1 ≤ x − 3 ≤ 4, giving the whole interval 4 ≤ x ≤ 7.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-119","question":"The roots z₁, z₂ of z² + az + b = 0 are such that 0, z₁, z₂ form an isosceles triangle with |z₁| = |z₂| and ∠z₁0z₂ = 120°. Then:","options":["a² = 3b","a² = b","a² = 2b","3a² = b"],"answer":1,"explanation":"Take z₂ = ωz₁ with ω = e^(2πi/3) (the other orientation uses ω², symmetric). Then a = −(z₁ + z₂) = −(1 + ω)z₁ = ω²z₁ and b = z₁z₂ = ωz₁². So a² = ω⁴z₁² = ωz₁² = b.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-120","question":"The centroid of an equilateral triangle in the Argand plane is 1 + i and one vertex is 3 + i. The product of the other two vertices is:","options":["2i","4 + 2i","2","−2"],"answer":2,"explanation":"With centroid c, the vertices are c + rω^k (k = 0, 1, 2), here r = 2. The product of the other two is (c + 2ω)(c + 2ω²) = c² + 2c(ω + ω²) + 4 = c² − 2c + 4. With c = 1 + i: 2i − 2 − 2i + 4 = 2.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-121","question":"The number of quadratic equations x² + px + q = 0 with integer p, q, p + q = 30 and both roots integers is:","options":["4","1","0","2"],"answer":3,"explanation":"If the roots are r, s then p = −(r + s), q = rs, and p + q = 30 gives rs − r − s = 30, i.e. (r − 1)(s − 1) = 31. Since 31 is prime, {r − 1, s − 1} = {1, 31} or {−1, −31}, giving roots {2, 32} or {0, −30}. Each unordered pair gives one equation: x² − 34x + 64 = 0 and x² + 30x = 0, so 2 equations.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-122","question":"The real quadratic ax² + bx + c = 0 has no real roots and a + b + c < 0. Which of the following is necessarily true?","options":["c > 0","a > 0","c < 0","b > 0"],"answer":2,"explanation":"With no real roots, f(x) = ax² + bx + c keeps one sign for all real x. f(1) = a + b + c < 0, so f(x) < 0 everywhere; in particular f(0) = c < 0 (and a < 0). The sign of b is not determined: −x² − 1 and −x² + x − 1 both qualify.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-123","question":"If α, β, γ are the roots of x³ − 2x² + 3x − 4 = 0, then α²β² + β²γ² + γ²α² equals:","options":["−7","7","25","−1"],"answer":0,"explanation":"With e₁ = 2, e₂ = 3, e₃ = 4: Σα²β² = (Σαβ)² − 2αβγ(α + β + γ) = 9 − 2 × 4 × 2 = −7. A negative sum of 'squares' is possible because two of the roots are non-real.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-124","question":"The value of Σ (k = 1 to 12) |e^(ikπ/6) − e^(i(k + 1)π/6)| is:","options":["12","6(√6 + √2)","2π","6(√6 − √2)"],"answer":3,"explanation":"Each term is a side of the regular 12-gon inscribed in the unit circle: |e^(iA) − e^(iB)| = 2 sin(|A − B|/2) = 2 sin 15°. The sum is 24 sin 15° = 24(√6 − √2)/4 = 6(√6 − √2) ≈ 6.21, slightly less than 2π.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-125","question":"For complex z with |z| = 1, the greatest value of |z³ − 3z + 2| is:","options":["4","3√3","6","2√3"],"answer":1,"explanation":"Factor: z³ − 3z + 2 = (z − 1)²(z + 2). With z = e^(iθ) and c = cos θ, |z − 1|² = 2 − 2c and |z + 2| = √(5 + 4c). Maximise (1 − c)²(5 + 4c): its derivative (1 − c)(−6 − 12c) vanishes at c = −1/2, giving |…| = 3 × √3 = 3√3 (larger than the value 4 at c = −1).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-126","question":"The number of real roots of (x² − 3x + 1)(x² + 5x + 1) = −16x² is:","options":["2","0","4","1"],"answer":1,"explanation":"x = 0 is not a root, so divide by x² and put u = x + 1/x: (u − 3)(u + 5) = −16, i.e. u² + 2u + 1 = 0, so u = −1. But x + 1/x = −1 means x² + x + 1 = 0, which has no real roots (|x + 1/x| ≥ 2 for real x). Indeed the equation is (x² + x + 1)² = 0.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-127","question":"The sum of the distinct real roots of x⁴ − 5x³ + 8x² − 5x + 1 = 0 is:","options":["5","3","6","4"],"answer":3,"explanation":"The equation is reciprocal; dividing by x² and putting t = x + 1/x gives t² − 5t + 6 = 0, so t = 2 or 3. t = 2 gives the double root x = 1; t = 3 gives x = (3 ± √5)/2, both real. The distinct real roots sum to 1 + 3 = 4 (5 would count the repeated root twice).","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-128","question":"The set of real k for which (k − 1)x² − 2kx + k + 3 < 0 for every real x is:","options":["the empty set","k < 1","k > 3/2","1 < k < 3/2"],"answer":0,"explanation":"We need a downward parabola with no real root: k − 1 < 0 and D/4 = k² − (k − 1)(k + 3) = 3 − 2k < 0. The second gives k > 3/2, which contradicts k < 1, and k = 1 gives the line −2x + 4, not always negative. So no k works.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"math-quadratic-complex-129","question":"Let f(x) = ax² + bx + c (a ≠ 0) with real coefficients be such that the equation f(x) = x has no real root. Then the equation f(f(x)) = x has:","options":["exactly two real roots","exactly four real roots","no real root","at least one real root"],"answer":2,"explanation":"f(x) − x keeps one sign, say f(x) > x for all real x. Then f(f(x)) > f(x) > x for every x, so f(f(x)) = x is impossible; similarly if f(x) < x everywhere. Hence f(f(x)) = x has no real root, even though it is a degree-4 equation.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
];

